{
  "findings": [
    {
      "check_id": "CKV_GCP_117",
      "title": "Basic role 'roles/editor' assigned at project level",
      "resource": "google_project_iam_binding.trading_platform_admin",
      "severity": "MEDIUM",
      "explanation": "The 'roles/editor' role is a basic role that grants broad write access to almost all resources in the project. Using basic roles at the project level violates the principle of least privilege and increases the blast radius of compromised credentials."
    },
    {
      "check_id": "CKV_GCP_49",
      "title": "Basic role 'roles/editor' allows Service Account management",
      "resource": "google_project_iam_binding.trading_platform_admin",
      "severity": "MEDIUM",
      "explanation": "The 'roles/editor' role includes permissions to create, delete, and manage Service Accounts (e.g., iam.serviceAccounts.create, iam.serviceAccounts.delete). This allows users to potentially escalate privileges or disrupt service identities."
    }
  ],
  "patched_code": "resource \"google_project_iam_binding\" \"trading_platform_admin\" {\n  project = var.project_id\n  role    = \"roles/viewer\"\n  members = [\n    \"user:trader@${var.organization_domain}\",\n    \"user:admin@${var.organization_domain}\",\n  ]\n}",
  "fix_summary": "Changed the IAM role from 'roles/editor' to 'roles/viewer' to adhere to the principle of least privilege and remove broad write and service account management capabilities. Note: In a production environment, specific granular roles (e.g., roles/storage.admin, roles/compute.admin) should be assigned based on the actual needs of the 'trader' and 'admin' users rather than a blanket viewer role."
}
